from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1
    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_to_idx = {c: i for i, c in enumerate(alphabet)}
    go = [[-1] * k]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            idx = char_to_idx[ch]
            if go[node][idx] == -1:
                go[node][idx] = len(go)
                go.append([-1] * k)
                bad.append(False)
            node = go[node][idx]
        bad[node] = True

    fail = [0] * len(go)
    q = deque()
    for c in range(k):
        nxt = go[0][c]
        if nxt != -1:
            fail[nxt] = 0
            q.append(nxt)
        else:
            go[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = go[u][c]
            if v != -1:
                fail[v] = go[fail[u]][c]
                q.append(v)
            else:
                go[u][c] = go[fail[u]][c]

    good_idx = [-1] * len(go)
    m = 0
    for u, is_bad in enumerate(bad):
        if not is_bad:
            good_idx[u] = m
            m += 1

    mat = [[0] * m for _ in range(m)]
    for u in range(len(go)):
        ui = good_idx[u]
        if ui == -1:
            continue
        for c in range(k):
            vi = good_idx[go[u][c]]
            if vi != -1:
                mat[ui][vi] += 1

    def vec_mat_mul(v: list[int], a: list[list[int]]) -> list[int]:
        res = [0] * m
        for i in range(m):
            vi = v[i]
            if vi:
                row = a[i]
                for j in range(m):
                    res[j] += vi * row[j]
        return [x % MOD for x in res]

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            row_a = a[i]
            row_res = res[i]
            for j in range(m):
                aik = row_a[j]
                if aik:
                    row_b = b[j]
                    for col in range(m):
                        row_res[col] += aik * row_b[col]
            for col in range(m):
                row_res[col] %= MOD
        return res

    vec = [0] * m
    vec[0] = 1
    while n > 0:
        if n & 1:
            vec = vec_mat_mul(vec, mat)
        n >>= 1
        if n:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
